project.solution:
function ticketPrice(age, isWeekend = false) {
  if (age < 5) {
    return 0;
  }
  let price = 15;
  if (age <= 12) {
    price = 8;
  } else if (age >= 65) {
    price = 10;
  }
  if (isWeekend) {
    price += 2;
  }
  return price;
}
